import { useEffect, useState } from 'react'
import { connect } from 'react-redux'
import { injectIntl } from 'react-intl'
import policyAction from '../../../redux/policy/actions'
import { Form } from 'antd'
import { useRouteMatch, useHistory } from 'react-router'
import {
  LazadaProductLiabilityEndorsement,
  Image,
  Header
} from './index.style'
import LanguageChangeButton from './components/LanguageChangeButton'
import Content from './components/Content'
import Footer from './components/Footer'
import sanitizePhoneNumber from '../../../helpers/sanitizePhoneNumber'

const { resetReduxPolicy, tokenizedDetailEndorsement, authorisedEndorsement } =
  policyAction

function LazadaProductLiability (props) {
  const router = useRouteMatch()
  const history = useHistory()
  const { getPolicyEndorsementDetailResult, policyEndorsement } = props
  const [requestData, setRequestData] = useState(null)
  const [endorsementData, setEndorsementData] = useState(null)
  const [policyStatus, setPolicyStatus] = useState('')
  const [currStep, setCurrStep] = useState(1)
  const [formInput, setFormInput] = useState({
    phone_no: { value: '', isValid: false },
    email: { value: '', isValid: false }
  })
  const [isSubmitted, setIsSubmitted] = useState(false)
  const packageIdMapping = {
    'lazadavn-msig-damageprotection': 'Asuransi Perlindungan Kerusakan',
    'lazadavn-msig-liability': 'Asuransi Perlindungan Konsumen'
  }

  const isNotLoading =
    requestData && Object.keys(requestData)?.length > 0 && currStep < 3

  const renderContent = () => {
    let type = 'loading'
    let wording = 'Memuat'
    let data = {
      policy_no: '',
      package_id: '',
      phone_no: { value: '' },
      email: { value: '' }
    }
    const isRequestData = requestData && Object.keys(requestData)?.length > 0
    if (policyStatus === 'CANCELLED' && currStep < 4) {
      type = 'error'
      wording =
        'Kebijakan Anda tidak lagi aktif, sehingga kami tidak dapat melanjutkan permintaan Anda. Untuk dukungan, silakan hubungi kami'
    } else {
      if (currStep === 1 && isRequestData) {
        type = 'info'
        wording = 'Nomor Polis Anda'
        data = {
          policy_no: requestData?.policy_number?.toUpperCase(),
          package_id: packageIdMapping[requestData?.package_id]
        }
      } else if (currStep === 2 && isRequestData) {
        type = 'form'
        wording =
          'Untuk melanjutkan proses pengajuan klaim, silakan lengkapi semua form di bawah ini'
        data = {
          phone_no: { value: formInput?.phone_no?.value },
          email: { value: formInput?.email?.value }
        }
      } else if (currStep === 3) {
        type = 'loading'
        wording =
          'Silakan tunggu sampai kami mengarahkan Anda ke Portal Pengajuan Klaim PasarPolis'
      }
    }
    return (
      <Content
        type={type}
        wording={wording}
        data={data}
        formInput={formInput}
        setFormInput={setFormInput}
        isDisabled={endorsementData && Object.keys(endorsementData)?.length > 0}
      />
    )
  }

  const handleSubmit = () => {
    const { token, id } = router.params
    const phoneNo = formInput?.phone_no?.value || requestData?.phone_no
    const email = formInput?.email?.value || requestData?.email
    const payload = {
      phone_no: sanitizePhoneNumber(phoneNo),
      email: email
    }
    if (
      (formInput?.phone_no?.isValid || requestData?.phone_no) &&
      (formInput?.email?.isValid || requestData?.email)
    ) {
      props.authorisedEndorsement({
        query: {
          internal_id: id,
          token: token
        },
        body: payload
      })
      setIsSubmitted(true)
    } else {
      setIsSubmitted(false)
      setCurrStep(2)
    }
  }

  const getRequestData = () => {
    const { id, token } = router.params
    const payload = {
      query: {
        id: id,
        token: token
      }
    }
    props.tokenizedDetailEndorsement(payload)
  }

  const moveNextStep = () => {
    setCurrStep(currStep + 1)
  }

  useEffect(() => {
    if (router?.params) {
      getRequestData()
    }
  }, [])

  useEffect(() => {
    if (currStep === 3) {
      handleSubmit()
    }
  }, [currStep])

  useEffect(() => {
    if (policyEndorsement?.error) {
      setIsSubmitted(false)
      setCurrStep(2)
    } else if (isSubmitted) {
      history.push('/')
    }
  }, [policyEndorsement])

  useEffect(() => {
    if (
      getPolicyEndorsementDetailResult &&
      Object.keys(getPolicyEndorsementDetailResult).length > 0
    ) {
      if (
        getPolicyEndorsementDetailResult?.endorsement &&
        Object.keys(getPolicyEndorsementDetailResult?.endorsement)?.length > 0
      ) {
        setRequestData({
          policy_number: getPolicyEndorsementDetailResult?.InsurancePolicyNo,
          package_id: getPolicyEndorsementDetailResult?.PackageCode,
          ...getPolicyEndorsementDetailResult?.endorsement
        })
        setFormInput({
          email: {
            value: getPolicyEndorsementDetailResult?.endorsement?.email
          },
          phone_no: {
            value: getPolicyEndorsementDetailResult?.endorsement?.phone_no
          }
        })
        setIsSubmitted(true)
        setCurrStep(3)
        history.push('/')
      } else {
        setRequestData(getPolicyEndorsementDetailResult?.Request)
        setFormInput({
          email: {
            value: getPolicyEndorsementDetailResult?.Request?.email
          },
          phone_no: {
            value: getPolicyEndorsementDetailResult?.Request?.phone_no
          }
        })
        setPolicyStatus(getPolicyEndorsementDetailResult?.PolicyState)
      }
      setEndorsementData(getPolicyEndorsementDetailResult?.endorsement)
    }
  }, [getPolicyEndorsementDetailResult])

  return (
    <LazadaProductLiabilityEndorsement>
      <Header>
        <LanguageChangeButton isNotLoading={isNotLoading} />
        <Image src='https://pp-img-prod.s3.ap-southeast-3.amazonaws.com/lazada/product_liability_vn/lazada_logo.svg' />
      </Header>
      {renderContent()}
      {isNotLoading && (
        <Footer
          step={currStep}
          moveNextStep={moveNextStep}
          isSubmitted={isSubmitted}
          isButtonVisible={policyStatus !== 'CANCELLED'}
        />
      )}
    </LazadaProductLiabilityEndorsement>
  )
}
const LazadaProductLiabilityWrapper = Form.create()(LazadaProductLiability)

export default connect(
  (state) => ({
    getPolicyEndorsementDetailResult: state.Policy.tokenisedEndorsementDetail,
    policyEndorsementDetailLoading: state.Loading.TOKENIZED_ENDORSEMENT_DETAIL,
    policyEndorsementDetailError: state.Error.TOKENIZED_ENDORSEMENT_DETAIL,
    policyEndorsement: state.Policy.authorizedEndorsementData,
    policyEndorsementMessage: state.Policy.authorizedEndorsementDataMessage,
    policyEndorsementLoading: state.Loading.AUTHORIZED_ENDORSEMENT,
    policyEndorsementError: state.Error.AUTHORIZED_ENDORSEMENT
  }),
  {
    authorisedEndorsement,
    tokenizedDetailEndorsement,
    resetReduxPolicy
  }
)(injectIntl(LazadaProductLiabilityWrapper))
