import { ContentWrapper, Form, Info, Loading } from './index.style'
import CircularLoader from '../../../../../components/CircularLoader'
import IntlMessages from '../../../../../components/utility/intlMessages'

function Content (props) {
  const renderContent = (type, wording, data = {}) => {
    switch (type) {
      case 'info':
        return (
          <Info>
            <img src='https://pp-img-prod.s3.ap-southeast-3.amazonaws.com/lazada/product_liability_vn/shield.svg' />
            <h4>
              <b>
                <IntlMessages id={data?.package_id} />
              </b>
            </h4>
            <p>
              <IntlMessages id={wording} />
            </p>
            <h5>{data?.policy_no}</h5>
          </Info>
        )
      case 'error':
        return (
          <Info>
            <h4>
              <b>
                <IntlMessages id={'Error'} />
              </b>
            </h4>
            <p>
              <IntlMessages id={wording} />
            </p>
          </Info>
        )
      case 'form':
        return (
          <>
            <p>
              <IntlMessages id={wording} />
            </p>
            <Form>
              <div>
                <input
                  type='text'
                  id='phone'
                  placeholder=' '
                  value={data?.phone_no?.value}
                  required
                  disabled={props.isDisabled}
                  onChange={(e) => {
                    const isValid = e.target.value.length > 0
                    props.setFormInput({
                      ...props?.formInput,
                      phone_no: {
                        value: e.target.value,
                        isValid: isValid
                      }
                    })
                  }}
                />
                <label htmlFor='phone' className='required'>
                  <IntlMessages id={'No Handphone'} />
                </label>
              </div>

              <div>
                <input
                  type='email'
                  id='email'
                  placeholder=' '
                  value={data?.email?.value}
                  required
                  disabled={props.isDisabled}
                  onChange={(e) => {
                    const isValid = e.target.value.length > 0
                    props.setFormInput({
                      ...props?.formInput,
                      email: { value: e.target.value, isValid: isValid }
                    })
                  }}
                />
                <label htmlFor='email' className='required'>
                  <IntlMessages id={'Alamat Email'} />
                </label>
              </div>
            </Form>
          </>
        )
      default:
        return (
          <Loading>
            <p>
              <IntlMessages id={wording} />
            </p>
            <CircularLoader size='32px' isSpining color='#fff' />
          </Loading>
        )
    }
  }

  return (
    <ContentWrapper>
      {renderContent(props?.type, props?.wording, props?.data)}
    </ContentWrapper>
  )
}

export default Content
