import { useState, useEffect } from 'react'
import { LanguageChangeButtonWrapper } from './index.style'
import appActions from '../../../../../redux/app/actions'
import { useDispatch } from 'react-redux'
import { listLangVietEng } from '../../../../../constants'

function LanguageChangeButton (props) {
  const { isNotLoading } = props
  const dispatch = useDispatch()
  const [isOpen, setIsOpen] = useState(false)
  const [selectedLang, setSelectedLang] = useState('vi')
  const languageMapping = { vi: 'Vietnamese', en: 'English' }

  const changeLanguagehandler = (lang) => {
    dispatch(appActions.changeLang(lang))
  }

  const handleLangClick = () => {
    if (!isOpen) {
      setIsOpen(true)
    }
  }

  const selectLang = (id) => {
    setSelectedLang(id)
    changeLanguagehandler(id)
    setIsOpen(false)
  }

  useEffect(() => {
    const lang = localStorage.lang
    if (lang) setSelectedLang(lang)
  }, [])

  return (
    <LanguageChangeButtonWrapper isOpen={isOpen} isNotLoading={isNotLoading}>
      <div className='btn__wrapper' onClick={handleLangClick}>
        {isOpen ? (
          <>
            {listLangVietEng.map((item, index) => (
              <p
                key={index}
                onClick={() => selectLang(item?.lang, item?.countryCode)}
              >
                {languageMapping[item?.lang]}
              </p>
            ))}
          </>
        ) : (
          <p>{languageMapping[selectedLang]}</p>
        )}
      </div>
    </LanguageChangeButtonWrapper>
  )
}

export default LanguageChangeButton
