import { Button } from 'antd'
import { FooterWrapper } from './index.style'
import IntlMessages from '../../../../../components/utility/intlMessages'

function Footer (props) {
  const { step, moveNextStep, isSubmitted, isButtonVisible } = props
  return (
    <FooterWrapper>
      {isButtonVisible && (
        <Button
          type='default'
          size='large'
          onClick={moveNextStep}
          disabled={isSubmitted && step >= 2}
        >
          <IntlMessages id={step === 1 ? 'Selanjutnya' : 'Submit'} />
        </Button>
      )}
      <p>
        <IntlMessages
          id={
            'Untuk bantuan lebih lanjut, silakan hubungi layanan pelanggan kami di Zalo OA: Pasarpolis VN'
          }
        />
      </p>
    </FooterWrapper>
  )
}

export default Footer
